Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
          | |- u8arr _ _ ?A _ => match goal with H : u8arr _ _ A _ |- _ => exact H end
          end
        | eassumption ].
Local Ltac fast_assumption :=
  lazymatch goal with
  | |- ?G => tryif has_evar G then assumption else
             first [ lazymatch G with
                     | rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
                     | ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
                     | bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
                     | u8arr _ _ ?A _ => match goal with H : u8arr _ _ A _ |- _ => exact H end
                     end
                   | assumption ]
  end.
(* [comment removed for export] *)
Local Ltac call_assignA e ::=
  let AS := fresh "AS" in
  pose proof assignA_spec as AS;
  unfold assignA_stmt, assign_stmt, assign_post, assign_W, P_EC_CTOR_HTTP, G_HTTP_CAT in AS;
  lazymatch goal with
  | |- evt _ _ (MS (mkR _ (Z_to_bv 64 ?spv) _ _ _ _ _ _ _ (Z_to_bv 64 ?D) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ _ _ _ _ _) =>
      lazymatch goal with
      | ST : stk _ _ ?lo _, HC : HttpCat _ ?g, TMP : rw_cells _ _ D [CB 24 ?junk] |- _ =>
          callZ (AS _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ D e lo g junk);
          [ exact TMP | exact HC | fast_assumption | rewrite ?unsigned_lit by lia; exact ST
          | rewrite ?unsigned_lit by lia; lia | lia | rewrite ?unsigned_lit by lia; lia | lia | lia | fast_assumption | clear AS ]
      end
  | |- evt _ _ (MS ?R _ _ _ _ _ _) =>
      fail "call_assignA: state not in mkR form; use call_assignA_with spv D e lo g junk"
  end.
Local Ltac call_assignA_with spv D e lo g junk ::=
  let AS := fresh "AS" in
  pose proof assignA_spec as AS;
  unfold assignA_stmt, assign_stmt, assign_post, assign_W, P_EC_CTOR_HTTP, G_HTTP_CAT in AS;
  callZ (AS _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ D e lo g junk);
  [ fast_assumption | fast_assumption | fast_assumption | rewrite ?unsigned_lit by lia; fast_assumption
  | rewrite ?unsigned_lit by lia; lia | lia | rewrite ?unsigned_lit by lia; lia | lia | lia | fast_assumption | clear AS ].

