Definition pf_W (lo : Z) (sp : word) (E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + 4184); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition pf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' p' E' g' (n1 n2 v1 v2 : word) bsz bb,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (pf_W lo sp E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' (oPP sp) [C8 (wz p')]
    /\ rw_cells usegs m' (oNM sp) [C8 n1; C8 n2]
    /\ rw_cells usegs m' (oVL sp) [C8 v1; C8 v2]
    /\ rw_cells usegs m' (oBF sp) [C8 (wz bsz); CB 4096 bb] /\ 0 <= bsz <= 4096
    /\ rw_cells usegs m' E (ErrCodeCells E')
    /\ bytes_at usegs m' p0 bs /\ PfTab m'
    /\ pf_out E0 E' p0 (p0 + Z.of_nat (length bs)) (oBF sp + 8) p' n1 n2 v1 v2 bsz
    /\ HttpCat m' g' /\ XStatics m'.

Definition pf_pure (sp : word) (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) : Prop :=
  ec_ok E0 /\ ec_failed E0 = false /\ lo + 240 <= bv_unsigned sp (* [comment removed for export] *) /\ 0xb8000 <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0x95090 <= p0) /\ p0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp + 4184 <= E /\ E + 24 <= 2^64.

Definition pf_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) (g : bool)
    (nm0 vl0 : list byte) (bsz0 : Z) (bb0 : list byte),
  rw_cells usegs m (oPP sp) [C8 (wz p0)] ->
  rw_cells usegs m (oNM sp) [CB 16 nm0] ->
  rw_cells usegs m (oVL sp) [CB 16 vl0] ->
  rw_cells usegs m (oBF sp) [C8 (wz bsz0); CB 4096 bb0] -> 0 <= bsz0 <= 4096 ->
  rw_cells usegs m E (ErrCodeCells E0) ->
  bytes_at usegs m p0 bs -> PfTab m ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) ->
  pf_pure sp E lo p0 bs E0 ->
  mem_inv usegs m ->
  evt usegs (pf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc E lo p0 bs E0 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (oPP sp)) (wz (p0 + Z.of_nat (length bs))) (wz (oNM sp)) (wz (oVL sp))
              (wz (oBF sp)) (wz E) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_FIELD) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition pf_ctx (m m1 : mem) (sp : word) (sv : list word) (E L lo : Z) (p0 : Z) (bs : list byte)
    (sa sb sc : word) (tl : list byte) (tmp : list cell) (pv : Z) (n1 n2 v1 v2 : word) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool)
  : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -160) [C8 sa; C8 sb; C8 sc]
  /\ rw_cells usegs m1 (bv_unsigned sp + -136) [CB 8 tl]
  /\ rw_cells usegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells usegs m1 (bv_unsigned sp + -104) (map C8 sv)
  /\ rw_cells usegs m1 (bv_unsigned sp + 40) [C8 (wz pv)]
  /\ rw_cells usegs m1 (bv_unsigned sp + 4168) [C8 n1; C8 n2]
  /\ rw_cells usegs m1 (bv_unsigned sp + 4152) [C8 v1; C8 v2]
  /\ rw_cells usegs m1 (bv_unsigned sp + 48) [C8 (wz bsz); CB 4096 bb]
  /\ rw_cells usegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at usegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ rw_cells usegs m1 543976 [C8 (wz 89246)]
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -160)
  /\ munch (pf_W lo sp E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

