Definition pf_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list word :=
  [s11; s10; s9; s8; s7; s6; s5; s4; s3; s2; s1; s0; ra].

(* [comment removed for export] *)
Definition pf_purei (sp : word) (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) : Prop :=
  pf_pure sp E lo p0 bs E0 /\ 0 <= bv_unsigned sp /\ bv_unsigned sp + 4184 <= 2^64.

Local Ltac pf_finish p' E' g' n1 n2 v1 v2 bsz bb :=
  apply evt_done; unfold pf_post, oPP, oNM, oVL, oBF, PfTab, PF_TABPTR, PF_TAB;
  do 16 eexists; exists p', E', g', n1, n2, v1, v2, bsz, bb;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.
Scheme kc__2 := Elimination for Corelib.Init.Logic.and Sort Prop.

Lemma pf_fail_exit : forall e loc,
  In e [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE] ->
